            files.append(os.path.join(dirpath, f))

results = []
for path in files:
    try:
        src = open(path, errors='replace').read()
    except Exception:
        continue
    for m in reg.finditer(src):
        line = src[:m.start()].count('\n') + 1
        # capture the full statement (up to 400 chars or balanced)
        seg = src[m.start():m.start()+500]
        results.append((path, line, seg.split(';')[0].replace('\n',' ')[:200]))

print(len(results))
for p, l, s in results:
    print(f"{p}:{l}: {s}")
EOF

